const userSessionByTokenHash = `-- name: UserSessionByTokenHash :one
SELECT s.id AS session_id, s.user_id AS session_user_id, s.kind, s.label, s.created_at AS session_created_at,
       s.last_used_at, s.expires_at, s.hard_expires_at, s.ip, s.user_agent,
       u.id, u.username, u.display_name, u.email, u.pending_email, u.pass_hash, u.email_verified_at, u.provider,
       u.provider_subject, u.created_at, u.last_login_at, u.disabled_at
FROM user_sessions s JOIN users u ON u.id = s.user_id
WHERE s.token_hash = $1
  AND s.ended_at IS NULL
  AND s.expires_at > $2
  AND (s.hard_expires_at IS NULL OR s.hard_expires_at > $2)
  AND u.disabled_at IS NULL
`

type UserSessionByTokenHashParams struct {
	TokenHash []byte             `json:"token_hash"`
	Now       pgtype.Timestamptz `json:"now"`
}

type UserSessionByTokenHashRow struct {
	SessionID        uuid.UUID          `json:"session_id"`
	SessionUserID    uuid.UUID          `json:"session_user_id"`
	Kind             string             `json:"kind"`
	Label            string             `json:"label"`
	SessionCreatedAt pgtype.Timestamptz `json:"session_created_at"`
	LastUsedAt       pgtype.Timestamptz `json:"last_used_at"`
	ExpiresAt        pgtype.Timestamptz `json:"expires_at"`
	HardExpiresAt    pgtype.Timestamptz `json:"hard_expires_at"`
	Ip               string             `json:"ip"`
	UserAgent        string             `json:"user_agent"`
	ID               uuid.UUID          `json:"id"`
	Username         string             `json:"username"`
	DisplayName      string             `json:"display_name"`
	Email            string             `json:"email"`
	PendingEmail     *string            `json:"pending_email"`
	PassHash         string             `json:"pass_hash"`
	EmailVerifiedAt  pgtype.Timestamptz `json:"email_verified_at"`
	Provider         string             `json:"provider"`
	ProviderSubject  *string            `json:"provider_subject"`
	CreatedAt        pgtype.Timestamptz `json:"created_at"`
	LastLoginAt      pgtype.Timestamptz `json:"last_login_at"`
	DisabledAt       pgtype.Timestamptz `json:"disabled_at"`
}

// A session is live when it is not ended, not past either expiry, and its user is not disabled.
func (q *Queries) UserSessionByTokenHash(ctx context.Context, arg UserSessionByTokenHashParams) (UserSessionByTokenHashRow, error) {
	row := q.db.QueryRow(ctx, userSessionByTokenHash, arg.TokenHash, arg.Now)
	var i UserSessionByTokenHashRow
	err := row.Scan(
		&i.SessionID,
		&i.SessionUserID,
		&i.Kind,
		&i.Label,
		&i.SessionCreatedAt,
		&i.LastUsedAt,
		&i.ExpiresAt,
		&i.HardExpiresAt,
		&i.Ip,
		&i.UserAgent,
		&i.ID,
		&i.Username,
		&i.DisplayName,
		&i.Email,
		&i.PendingEmail,
		&i.PassHash,
		&i.EmailVerifiedAt,
		&i.Provider,
		&i.ProviderSubject,
		&i.CreatedAt,
		&i.LastLoginAt,
		&i.DisabledAt,
	)
	return i, err
}

const userSessionLive = `-- name: UserSessionLive :one
SELECT EXISTS (
    SELECT 1 FROM user_sessions
    WHERE id = $1 AND user_id = $2 AND ended_at IS NULL AND expires_at > now()
      AND (hard_expires_at IS NULL OR hard_expires_at > now())
)::boolean
`

type UserSessionLiveParams struct {
	ID     uuid.UUID `json:"id"`
	UserID uuid.UUID `json:"user_id"`
}

func (q *Queries) UserSessionLive(ctx context.Context, arg UserSessionLiveParams) (bool, error) {
	row := q.db.QueryRow(ctx, userSessionLive, arg.ID, arg.UserID)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}
